const session = $input.first().json;
const payload = session.state_payload || {};

// Build the order creation payload for Heroku API
const orderPayload = {
  route_id: payload.route_id,
  trip_id: payload.trip_id,
  payment_method: 'PIX',
  search_trip: 'one_way',
  name: payload.passenger_name || session.full_name,
  phone: payload.passenger_phone || session.phone_number,
  date: payload.travel_date,
  return_date: null,
  documents: { '1': payload.passenger_cpf || session.cpf },
  customers: { '1': payload.passenger_name || session.full_name },
  birthdays: { '1': payload.passenger_birthday || '1990-01-01' },
  phones: { '1': payload.passenger_phone || session.phone_number },
  document_types: { '1': 'CPF' },
  data: JSON.stringify([{ speed_boat_price: 1 }, { hammock_price: 0 }, { suite_price1: 0 }, { suite_price2: 0 }])
};

return [{
  json: {
    orderPayload,
    phone_number: payload.passenger_phone || session.phone_number,
    passenger_name: payload.passenger_name || session.full_name,
    session_id: $('Execute Trigger').item.json.session_id
  }
}];

const orderResponse = $input.first().json;
const triggerData = $('Execute Trigger').item.json;

// Extract data from Heroku order response
const orderId = orderResponse.id;
const paymentLink = orderResponse.payment_link || orderResponse.payment_url || `https://embarcar-e83ea296df06.herokuapp.com/orders/${orderId}`;
const customers = orderResponse.customers || [];
const customerId = customers.length > 0 ? customers[0].id : null;

// Voucher URL is always /orders/{id}
const voucherUrl = `https://embarcar-e83ea296df06.herokuapp.com/orders/${orderId}`;

return [{
  json: {
    order_id: orderId,
    payment_link: paymentLink,
    voucher_url: voucherUrl,
    customers,
    customer_id: customerId,
    phone_number: triggerData.phone_number || $('Prepare Order Payload').item.json.phone_number,
    passenger_name: $('Prepare Order Payload').item.json.passenger_name,
    session_id: triggerData.session_id
  }
}];

